          "id": "code-ml-34-2-ch34_2_sklearn",
          "title": "Scikit-Learn 1.9: GP-BO (Matérn 5/2 + Exact EI) vs TPE KDE (l/g) vs Random Search pada SVC-RBF",
          "language": "python",
          "filename": "34_2_sklearn_gp_bo_vs_tpe_svc.py",
          "code": "import numpy as np\nfrom scipy.stats import norm, qmc\nfrom sklearn.datasets import make_classification\nfrom sklearn.gaussian_process import GaussianProcessRegressor\nfrom sklearn.gaussian_process.kernels import ConstantKernel, Matern, WhiteKernel\nfrom sklearn.metrics import log_loss\nfrom sklearn.model_selection import StratifiedKFold\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import SVC\n\n# -----------------------------------------------------------------------------\n# Scikit-Learn 1.9: GP-BO (Matern 5/2 + Exact EI) vs TPE KDE (l/g) vs Random\n# Menala 2 hyperparameter sensitif SVC-RBF: log10(C) in [-2, 3], log10(gamma) in [-4, 0]\n# pada 3-Fold Stratified CV Log-Loss (Pipeline bebas data leakage!)\n# -----------------------------------------------------------------------------\nX, y = make_classification(\n    n_samples=360, n_features=14, n_informative=6, n_redundant=3,\n    class_sep=0.95, flip_y=0.03, random_state=3422\n)\ncv = StratifiedKFold(n_splits=3, shuffle=True, random_state=42)\n\ndef eval_svc_cv(u: np.ndarray) -> float:\n    C = float(10.0 ** (-2.0 + 5.0 * u[0]))\n    gamma = float(10.0 ** (-4.0 + 4.0 * u[1]))\n    losses = []\n    for tr, va in cv.split(X, y):\n        pipe = Pipeline([\n            (\"sc\", StandardScaler()),\n            (\"svc\", SVC(C=C, gamma=gamma, kernel=\"rbf\", probability=True, max_iter=1500, random_state=42)),\n        ])\n        pipe.fit(X[tr], y[tr])\n        losses.append(log_loss(y[va], pipe.predict_proba(X[va])[:, 1]))\n    return float(np.mean(losses))\n\ndef local_bw(obs: np.ndarray) -> np.ndarray:\n    n = len(obs)\n    if n <= 1:\n        return np.full(n, 0.20)\n    ord_i = np.argsort(obs)\n    s = obs[ord_i]\n    bw_s = np.empty(n)\n    bw_s[0] = max(s[1] - s[0], s[0])\n    bw_s[-1] = max(s[-1] - s[-2], 1.0 - s[-1])\n    if n > 2:\n        bw_s[1:-1] = np.maximum(s[1:-1] - s[:-2], s[2:] - s[1:-1])\n    out = np.empty(n)\n    out[ord_i] = np.clip(bw_s, 0.03, 0.30)\n    return out\n\nT_BUDGET, N_INIT = 24, 8\nrng = np.random.default_rng(7)\n\n# 1. Random Search (24 trial)\nU_rand = rng.uniform(0.0, 1.0, size=(T_BUDGET, 2))\ny_rand = np.array([eval_svc_cv(u) for u in U_rand])\n\n# Startup Sobol bersama untuk GP-BO dan TPE (8 titik = 2^3)\ninit_pts = qmc.Sobol(d=2, scramble=True, rng=np.random.default_rng(42)).random_base2(m=3)\ninit_y = [eval_svc_cv(u) for u in init_pts]\ncand_pool = qmc.Sobol(d=2, scramble=True, rng=np.random.default_rng(777)).random_base2(m=9)\n\n# 2. GP-BO (Matern 5/2 + Expected Improvement)\nX_gp, y_gp = list(init_pts), list(init_y)\nfor _ in range(T_BUDGET - N_INIT):\n    kernel = ConstantKernel(1.0, (1e-2, 1e2)) * Matern(length_scale=[0.3, 0.3], nu=2.5) + WhiteKernel(1e-4)\n    gp = GaussianProcessRegressor(kernel=kernel, normalize_y=True, n_restarts_optimizer=0, random_state=42)\n    gp.fit(np.array(X_gp), np.array(y_gp))\n    mu, std = gp.predict(cand_pool, return_std=True)\n    imp = float(np.min(y_gp)) - mu - 0.002\n    z = np.where(std > 1e-9, imp / std, 0.0)\n    ei = np.where(std > 1e-9, imp * norm.cdf(z) + std * norm.pdf(z), 0.0)\n    u_next = cand_pool[int(np.argmax(ei))]\n    X_gp.append(u_next)\n    y_gp.append(eval_svc_cv(u_next))\n\n# 3. TPE KDE (l(x)/g(x)) dengan local adaptive bandwidth\nX_tpe, y_tpe = list(init_pts), list(init_y)\nfor t in range(N_INIT, T_BUDGET):\n    Xa, ya = np.array(X_tpe), np.array(y_tpe)\n    ord_i = np.argsort(ya)\n    n_g = max(2, int(np.ceil(0.25 * t)))\n    G, B = Xa[ord_i[:n_g]], Xa[ord_i[n_g:]]\n    log_ratio = np.zeros(len(cand_pool))\n    for d in range(2):\n        bw_g, bw_b = local_bw(G[:, d]), local_bw(B[:, d])\n        l_d = (np.sum(norm.pdf((cand_pool[:, d:d+1] - G[:, d]) / bw_g[None, :]) / bw_g[None, :], axis=1) + 0.5) / (len(G) + 0.5)\n        g_d = (np.sum(norm.pdf((cand_pool[:, d:d+1] - B[:, d]) / bw_b[None, :]) / bw_b[None, :], axis=1) + 0.5) / (len(B) + 0.5)\n        log_ratio += np.log(np.maximum(l_d, 1e-12)) - np.log(np.maximum(g_d, 1e-12))\n    u_next = cand_pool[int(np.argmax(log_ratio))]\n    X_tpe.append(u_next)\n    y_tpe.append(eval_svc_cv(u_next))\n\nprint(f\"=== HPO Pipeline(StandardScaler, SVC-RBF) (3-Fold CV Log-Loss, Budget={T_BUDGET} Trial) ===\")\nfor name, Xs, ys in [\n    (\"1. Random Search     \", U_rand, y_rand),\n    (\"2. GP-BO (Matern EI) \", np.array(X_gp), np.array(y_gp)),\n    (\"3. TPE KDE (l/g)     \", np.array(X_tpe), np.array(y_tpe)),\n]:\n    bi = int(np.argmin(ys))\n    C_b = 10.0 ** (-2.0 + 5.0 * Xs[bi, 0])\n    g_b = 10.0 ** (-4.0 + 4.0 * Xs[bi, 1])\n    print(f\"{name} | Best CV LogLoss={ys[bi]:.4f} (@trial {bi+1:2d}) | Mean Top-5={np.sort(ys)[:5].mean():.4f} | C={C_b:.3f}, gamma={g_b:.5f}\")",
          "expectedOutput": "=== HPO Pipeline(StandardScaler, SVC-RBF) (3-Fold CV Log-Loss, Budget=24 Trial) ===\n1. Random Search      | Best CV LogLoss=0.3877 (@trial 23) | Mean Top-5=0.4137 | C=15.797, gamma=0.09270\n2. GP-BO (Matern EI)  | Best CV LogLoss=0.3527 (@trial 14) | Mean Top-5=0.3585 | C=3.351, gamma=0.09201\n3. TPE KDE (l/g)      | Best CV LogLoss=0.3572 (@trial 12) | Mean Top-5=0.3643 | C=9.100, gamma=0.06950",
          "actualOutput": "=== HPO Pipeline(StandardScaler, SVC-RBF) (3-Fold CV Log-Loss, Budget=24 Trial) ===\n1. Random Search      | Best CV LogLoss=0.3877 (@trial 23) | Mean Top-5=0.4137 | C=15.797, gamma=0.09270\n2. GP-BO (Matern EI)  | Best CV LogLoss=0.3527 (@trial 14) | Mean Top-5=0.3585 | C=3.351, gamma=0.09201\n3. TPE KDE (l/g)      | Best CV LogLoss=0.3572 (@trial 12) | Mean Top-5=0.3643 | C=9.100, gamma=0.06950",
          "explanation": "Menala Pipeline(StandardScaler, SVC-RBF) selama 24 trial (8 startup Sobol + 16 adaptif): GP-BO Matérn 5/2 mencetak Best CV LogLoss terendah 0.3527 (@trial 14, Mean Top-5 0.3585), TPE KDE menyamai sangat ketat di 0.3572 (@trial 12, Mean Top-5 0.3643), keduanya jauh melampaui Random Search (0.3877, Mean Top-5 0.4137).",
