          "id": "code-ml-34-2-ch34_2_diag",
          "title": "Production Audit: Skalabilitas FLOPs GP O(T^3) vs TPE O(T) & Ghost-Mode Trap (Independent vs Multivariate TPE)",
          "language": "python",
          "filename": "34_2_gp_cholesky_scaling_and_multivariate_tpe_audit.py",
          "code": "import numpy as np\nfrom scipy.stats import norm, qmc\n\n# -----------------------------------------------------------------------------\n# Production Audit:\n#   1. Skalabilitas Matematis Surrogate: GP Cholesky O(T^3) vs TPE O(T * D * K)\n#   2. Independent TPE (Ghost-Mode Trap!) vs Multivariate Joint TPE (Optuna!)\n#      pada Lanskap Interaksi Kopling Kuat (lr x n_estimators)\n# -----------------------------------------------------------------------------\nprint(\"=== 1. Audit Skalabilitas Komputasi Surrogate per Iterasi (D=15, K=24 Kandidat) ===\")\nD_s, K_s = 15, 24\nfor T in [50, 200, 500, 1000, 2000]:\n    gp_flops = (T ** 3) // 3 + 2 * (T ** 2) * 512\n    tpe_flops = T * D_s * K_s * 4\n    gp_ram_mb = (T * T * 8) / (1024 ** 2)\n    print(f\"T={T:4d} | GP Cholesky ~{gp_flops/1e6:8.2f}M FLOPs (RAM Matriks={gp_ram_mb:5.2f} MB) | TPE ~{tpe_flops/1e6:6.3f}M FLOPs | Rasio GP/TPE={gp_flops/tpe_flops:7.1f}x\")\n\ndef coupled_hpo(u: np.ndarray) -> np.ndarray:\n    # Meniru kopling pasangan (lr kecil + trees banyak) ATAU (lr besar + trees sedikit):\n    # Sudut silang (0.18, 0.18) dan (0.82, 0.82) adalah jebakan Ghost Mode bagi Independent TPE!\n    b1 = 0.06 + 8.0 * ((u[..., 0] - 0.18) ** 2 + (u[..., 1] - 0.82) ** 2)\n    b2 = 0.00 + 8.0 * ((u[..., 0] - 0.82) ** 2 + (u[..., 1] - 0.18) ** 2)\n    b3 = 0.04 + 6.0 * ((u[..., 2] - 0.22) ** 2 + (u[..., 3] - 0.78) ** 2)\n    b4 = 0.00 + 6.0 * ((u[..., 2] - 0.78) ** 2 + (u[..., 3] - 0.22) ** 2)\n    return np.minimum(b1, b2) + np.minimum(b3, b4)\n\ndef run_tpe_coupling(multivariate: bool, seed: int, T_tot: int = 64, n_init: int = 16) -> float:\n    rng = np.random.default_rng(seed)\n    D = 4\n    init = qmc.Sobol(d=D, scramble=True, rng=np.random.default_rng(seed)).random_base2(m=4)\n    X, y = list(init), [float(coupled_hpo(p)) for p in init]\n    for t in range(n_init, T_tot):\n        Xa, ya = np.array(X), np.array(y)\n        ord_i = np.argsort(ya)\n        ng = max(4, int(np.ceil(0.20 * t)))\n        G, B = Xa[ord_i[:ng]], Xa[ord_i[ng:]]\n        nc = 64\n        bw_g = np.clip(0.8 * np.std(G, axis=0) * (len(G) ** (-1.0 / (D + 4))), 0.04, 0.25)\n        bw_b = np.clip(0.8 * np.std(B, axis=0) * (len(B) ** (-1.0 / (D + 4))), 0.06, 0.30)\n        if not multivariate:\n            # Independent TPE: produk marginal per sumbu -> menciptakan Ghost Modes!\n            cand = np.column_stack([\n                np.clip(G[rng.integers(0, len(G), size=nc), d] + rng.normal(0.0, bw_g[d], size=nc), 0.0, 1.0)\n                for d in range(D)\n            ])\n            lr = np.zeros(nc)\n            for d in range(D):\n                ld = (norm.pdf((cand[:, d:d+1] - G[:, d]) / bw_g[d]).sum(axis=1) / bw_g[d] + 0.5) / (len(G) + 0.5)\n                gd = (norm.pdf((cand[:, d:d+1] - B[:, d]) / bw_b[d]).sum(axis=1) / bw_b[d] + 0.5) / (len(B) + 0.5)\n                lr += np.log(np.maximum(ld, 1e-12)) - np.log(np.maximum(gd, 1e-12))\n        else:\n            # Multivariate TPE (Optuna Joint Mixture of Product Kernels): bebas Ghost Modes!\n            k_pick = rng.integers(0, len(G), size=nc)\n            cand = np.clip(G[k_pick] + rng.normal(0.0, 1.0, size=(nc, D)) * bw_g[None, :], 0.0, 1.0)\n            log_k_g = np.sum(norm.logpdf((cand[:, None, :] - G[None, :, :]) / bw_g[None, None, :]) - np.log(bw_g[None, None, :]), axis=2)\n            log_k_b = np.sum(norm.logpdf((cand[:, None, :] - B[None, :, :]) / bw_b[None, None, :]) - np.log(bw_b[None, None, :]), axis=2)\n            ld = (np.exp(np.clip(log_k_g, -50, 50)).sum(axis=1) + 0.5) / (len(G) + 0.5)\n            gd = (np.exp(np.clip(log_k_b, -50, 50)).sum(axis=1) + 0.5) / (len(B) + 0.5)\n            lr = np.log(np.maximum(ld, 1e-12)) - np.log(np.maximum(gd, 1e-12))\n        u_next = cand[int(np.argmax(lr))]\n        X.append(u_next)\n        y.append(float(coupled_hpo(u_next)))\n    return float(np.min(y))\n\nind = np.array([run_tpe_coupling(False, 800 + i) for i in range(25)])\nmv = np.array([run_tpe_coupling(True, 800 + i) for i in range(25)])\nprint(\"\\n=== 2. Audit Interaksi Kopling 4D (Ghost-Mode Trap, f*=0.0000, 25 Ulangan, T=64) ===\")\nprint(f\"Independent TPE (multivariate=False) | Mean Best={ind.mean():.5f} | Median={np.median(ind):.5f}\")\nprint(f\"Multivariate TPE (multivariate=True) | Mean Best={mv.mean():.5f} | Median={np.median(mv):.5f} ({ind.mean()/mv.mean():.2f}x Mean, {np.median(ind)/np.median(mv):.2f}x Median!)\")",
          "expectedOutput": "=== 1. Audit Skalabilitas Komputasi Surrogate per Iterasi (D=15, K=24 Kandidat) ===\nT=  50 | GP Cholesky ~    2.60M FLOPs (RAM Matriks= 0.02 MB) | TPE ~ 0.072M FLOPs | Rasio GP/TPE=   36.1x\nT= 200 | GP Cholesky ~   43.63M FLOPs (RAM Matriks= 0.31 MB) | TPE ~ 0.288M FLOPs | Rasio GP/TPE=  151.5x\nT= 500 | GP Cholesky ~  297.67M FLOPs (RAM Matriks= 1.91 MB) | TPE ~ 0.720M FLOPs | Rasio GP/TPE=  413.4x\nT=1000 | GP Cholesky ~ 1357.33M FLOPs (RAM Matriks= 7.63 MB) | TPE ~ 1.440M FLOPs | Rasio GP/TPE=  942.6x\nT=2000 | GP Cholesky ~ 6762.67M FLOPs (RAM Matriks=30.52 MB) | TPE ~ 2.880M FLOPs | Rasio GP/TPE= 2348.1x\n\n=== 2. Audit Interaksi Kopling 4D (Ghost-Mode Trap, f*=0.0000, 25 Ulangan, T=64) ===\nIndependent TPE (multivariate=False) | Mean Best=0.24265 | Median=0.23512\nMultivariate TPE (multivariate=True) | Mean Best=0.16191 | Median=0.11567 (1.50x Mean, 2.03x Median!)",
          "actualOutput": "=== 1. Audit Skalabilitas Komputasi Surrogate per Iterasi (D=15, K=24 Kandidat) ===\nT=  50 | GP Cholesky ~    2.60M FLOPs (RAM Matriks= 0.02 MB) | TPE ~ 0.072M FLOPs | Rasio GP/TPE=   36.1x\nT= 200 | GP Cholesky ~   43.63M FLOPs (RAM Matriks= 0.31 MB) | TPE ~ 0.288M FLOPs | Rasio GP/TPE=  151.5x\nT= 500 | GP Cholesky ~  297.67M FLOPs (RAM Matriks= 1.91 MB) | TPE ~ 0.720M FLOPs | Rasio GP/TPE=  413.4x\nT=1000 | GP Cholesky ~ 1357.33M FLOPs (RAM Matriks= 7.63 MB) | TPE ~ 1.440M FLOPs | Rasio GP/TPE=  942.6x\nT=2000 | GP Cholesky ~ 6762.67M FLOPs (RAM Matriks=30.52 MB) | TPE ~ 2.880M FLOPs | Rasio GP/TPE= 2348.1x\n\n=== 2. Audit Interaksi Kopling 4D (Ghost-Mode Trap, f*=0.0000, 25 Ulangan, T=64) ===\nIndependent TPE (multivariate=False) | Mean Best=0.24265 | Median=0.23512\nMultivariate TPE (multivariate=True) | Mean Best=0.16191 | Median=0.11567 (1.50x Mean, 2.03x Median!)",
