          "id": "code-ml-34-4-ch34_4_scratch",
          "title": "First-Principles NumPy: Fast Non-Dominated Sorting, Exact 2D Hypervolume & Bukti Kebutaan Linear Scalarization",
          "language": "python",
          "filename": "34_4_pareto_front_hv2d_nonconvex_scratch.py",
          "code": "import numpy as np\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy:\n#   1. Fast Non-Dominated Sorting (Front F1, F2, ...) & Exact 2D Hypervolume\n#   2. Bukti Mengapa Linear Scalarization Buta terhadap Frontier Non-Konveks!\n# -----------------------------------------------------------------------------\ndef fast_non_dominated_sort(costs: np.ndarray) -> list[list[int]]:\n    n = len(costs)\n    dom_set = [[] for _ in range(n)]\n    dom_cnt = np.zeros(n, dtype=int)\n    fronts = [[]]\n    for p in range(n):\n        for q in range(n):\n            if p == q:\n                continue\n            if np.all(costs[p] <= costs[q]) and np.any(costs[p] < costs[q]):\n                dom_set[p].append(q)\n            elif np.all(costs[q] <= costs[p]) and np.any(costs[q] < costs[p]):\n                dom_cnt[p] += 1\n        if dom_cnt[p] == 0:\n            fronts[0].append(p)\n    i = 0\n    while i < len(fronts) and fronts[i]:\n        nxt = []\n        for p in fronts[i]:\n            for q in dom_set[p]:\n                dom_cnt[q] -= 1\n                if dom_cnt[q] == 0:\n                    nxt.append(q)\n        i += 1\n        if nxt:\n            fronts.append(nxt)\n    return fronts\n\ndef hypervolume_2d(pareto_costs: np.ndarray, ref_pt: np.ndarray) -> float:\n    valid = pareto_costs[np.all(pareto_costs < ref_pt, axis=1)]\n    if len(valid) == 0:\n        return 0.0\n    pts = valid[np.argsort(valid[:, 0])]\n    hv = 0.0\n    prev_y = float(ref_pt[1])\n    for x, y in pts:\n        if y < prev_y:\n            hv += float(ref_pt[0] - x) * (prev_y - float(y))\n            prev_y = float(y)\n    return hv\n\nnames = [\"M0(Akurat-Lambat)\", \"M1(Cekung-A)\", \"M2(Cekung-Knee)\", \"M3(Cekung-B)\", \"M4(Cepat-Kasar)\", \"M5(Dominated)\", \"M6(Dominated)\"]\ncosts = np.array([\n    [0.08, 0.90],\n    [0.30, 0.78],\n    [0.52, 0.60],\n    [0.72, 0.36],\n    [0.88, 0.10],\n    [0.58, 0.70],\n    [0.80, 0.50],\n])\nfronts = fast_non_dominated_sort(costs)\nf1_idx = sorted(fronts[0], key=lambda idx: costs[idx, 0])\nref_pt = np.array([1.0, 1.0])\nhv_all = hypervolume_2d(costs[f1_idx], ref_pt)\n\nweights = np.linspace(0.0, 1.0, 1001)\nlin_winners = {int(np.argmin(w * costs[:, 0] + (1.0 - w) * costs[:, 1])) for w in weights}\n\nprint(\"=== 1. Non-Dominated Sorting & 2D Hypervolume (Ref=[1.0, 1.0]) ===\")\nfor fi, fr in enumerate(fronts, 1):\n    print(f\"  Front F{fi}: {[names[i] for i in fr]}\")\nprint(f\"  Exact 2D Hypervolume Front F1 = {hv_all:.6f}\")\n\nprint(\"\\n=== 2. Bukti Kegagalan Linear Scalarization pada Frontier Non-Konveks ===\")\nprint(f\"  Jumlah titik Pareto sejati (F1)       : {len(f1_idx)} -> {[names[i] for i in f1_idx]}\")\nprint(f\"  Titik yang PERNAH menang Linear w*f1+(1-w)f2 (1001 bobot): {[names[i] for i in sorted(lin_winners)]}\")\nmissed = [names[i] for i in f1_idx if i not in lin_winners]\nprint(f\"  Titik Pareto MUSTAHIL ditemukan Linear Scalarization     : {missed} <-- BUTA TOTAL!\")",
