          "id": "code-ml-34-4-ch34_4_diag",
          "title": "Production Audit: Many-Objective Curse (M=2..6), Hybrid Warm-Start di Drift vs Shift & SHA-256 Reproducibility Manifest",
          "language": "python",
          "filename": "34_4_many_obj_curse_warmstart_sha256_audit.py",
          "code": "import hashlib\nimport json\nimport numpy as np\n\n# -----------------------------------------------------------------------------\n# Production Audit:\n#   1. Many-Objective Curse (M=2..6): Persentase Titik Acak Non-Dominated\n#   2. Warm-Starting HPO: Mild Drift vs Severe Shift (Cold vs PureWarm vs Hybrid)\n#   3. Deterministic Artifact & Study Reproducibility Fingerprint (SHA-256)\n# -----------------------------------------------------------------------------\nrng = np.random.default_rng(3443)\nprint(\"=== 1. Audit Many-Objective Curse (N=150 Kandidat Acak di [0,1]^M) ===\")\nfor M in [2, 3, 4, 5, 6]:\n    pts = rng.uniform(0.0, 1.0, size=(150, M))\n    nd = 0\n    for i in range(len(pts)):\n        dom = np.any(np.all(pts <= pts[i], axis=1) & np.any(pts < pts[i], axis=1))\n        nd += int(not dom)\n    status = \"Seleksi Pareto Tajam\" if nd / 150 < 0.35 else \"PARETO COLLAPSE (ubah ke constraints!)\"\n    print(f\"  M={M} objektif | Non-Dominated={nd:3d}/150 ({nd/150:5.1%}) -> {status}\")\n\ndef loss_fn(x: np.ndarray, opt: np.ndarray) -> np.ndarray:\n    return np.sum((x - opt) ** 2, axis=-1)\n\nprev_pareto = np.array([[0.22, 0.28], [0.25, 0.24], [0.27, 0.30], [0.21, 0.25], [0.24, 0.26]])\n\ndef run_retrain_hpo(opt_new: np.ndarray, mode: str, n_budget: int = 20, seed: int = 42) -> float:\n    r = np.random.default_rng(seed)\n    if mode == \"cold\":\n        cands = r.uniform(0.0, 1.0, size=(n_budget, 2))\n    elif mode == \"pure_warm\":\n        base = prev_pareto[r.integers(0, len(prev_pareto), size=n_budget)]\n        cands = np.clip(base + r.normal(0.0, 0.06, size=(n_budget, 2)), 0.0, 1.0)\n    else:\n        loc = np.clip(prev_pareto + r.normal(0.0, 0.06, size=prev_pareto.shape), 0.0, 1.0)\n        glob = r.uniform(0.0, 1.0, size=(n_budget - 2 * len(prev_pareto), 2))\n        cands = np.vstack([prev_pareto, loc, glob])\n    return float(loss_fn(cands, opt_new).min())\n\nprint(\"\\n=== 2. Audit Warm-Starting HPO (Budget=20 Trial, Rata-Rata 30 Ulangan) ===\")\nfor scenario, opt_new in [(\"Mild Drift   (opt=[0.28, 0.31])\", np.array([0.28, 0.31])),\n                          (\"Severe Shift (opt=[0.80, 0.78])\", np.array([0.80, 0.78]))]:\n    res = {m: float(np.mean([run_retrain_hpo(opt_new, m, seed=900 + i) for i in range(30)]))\n           for m in [\"cold\", \"pure_warm\", \"hybrid\"]}\n    print(f\"  {scenario} | Cold={res['cold']:.5f} | PureWarm={res['pure_warm']:.5f} | Hybrid(50/50)={res['hybrid']:.5f}\")\n\nmanifest = {\n    \"study_name\": \"bnpl_fraud_moo_v2026_04\",\n    \"sampler\": {\"name\": \"MOTPE\", \"seed\": 42, \"multivariate\": True, \"n_startup_trials\": 16},\n    \"dataset_sha256\": hashlib.sha256(b\"bnpl_2026q1_train_v3_rows_150000\").hexdigest()[:16],\n    \"sla_constraints\": {\"p99_max\": 10.0, \"artifact_kb_max\": 150.0},\n    \"selected_trial\": {\"max_iter\": 74, \"max_leaf_nodes\": 8, \"learning_rate\": 0.0553},\n}\ncanon_json = json.dumps(manifest, sort_keys=True, separators=(\",\", \":\"))\nfp1 = hashlib.sha256(canon_json.encode(\"utf-8\")).hexdigest()\nfp2 = hashlib.sha256(json.dumps(manifest, sort_keys=True, separators=(\",\", \":\")).encode(\"utf-8\")).hexdigest()\nprint(\"\\n=== 3. Audit Reproducibility Manifest Fingerprint ===\")\nprint(f\"  Canonical SHA-256 Run-1 : {fp1[:24]}...\")\nprint(f\"  Canonical SHA-256 Run-2 : {fp2[:24]}... | Identik 100%={fp1 == fp2}\")",
          "expectedOutput": "=== 1. Audit Many-Objective Curse (N=150 Kandidat Acak di [0,1]^M) ===\n  M=2 objektif | Non-Dominated=  5/150 ( 3.3%) -> Seleksi Pareto Tajam\n  M=3 objektif | Non-Dominated= 19/150 (12.7%) -> Seleksi Pareto Tajam\n  M=4 objektif | Non-Dominated= 45/150 (30.0%) -> Seleksi Pareto Tajam\n  M=5 objektif | Non-Dominated= 64/150 (42.7%) -> PARETO COLLAPSE (ubah ke constraints!)\n  M=6 objektif | Non-Dominated= 73/150 (48.7%) -> PARETO COLLAPSE (ubah ke constraints!)\n\n=== 2. Audit Warm-Starting HPO (Budget=20 Trial, Rata-Rata 30 Ulangan) ===\n  Mild Drift   (opt=[0.28, 0.31]) | Cold=0.01220 | PureWarm=0.00071 | Hybrid(50/50)=0.00019\n  Severe Shift (opt=[0.80, 0.78]) | Cold=0.01653 | PureWarm=0.41578 | Hybrid(50/50)=0.03190\n\n=== 3. Audit Reproducibility Manifest Fingerprint ===\n  Canonical SHA-256 Run-1 : f976e0c71d14c97c8cd0d742...\n  Canonical SHA-256 Run-2 : f976e0c71d14c97c8cd0d742... | Identik 100%=True",
          "actualOutput": "=== 1. Audit Many-Objective Curse (N=150 Kandidat Acak di [0,1]^M) ===\n  M=2 objektif | Non-Dominated=  5/150 ( 3.3%) -> Seleksi Pareto Tajam\n  M=3 objektif | Non-Dominated= 19/150 (12.7%) -> Seleksi Pareto Tajam\n  M=4 objektif | Non-Dominated= 45/150 (30.0%) -> Seleksi Pareto Tajam\n  M=5 objektif | Non-Dominated= 64/150 (42.7%) -> PARETO COLLAPSE (ubah ke constraints!)\n  M=6 objektif | Non-Dominated= 73/150 (48.7%) -> PARETO COLLAPSE (ubah ke constraints!)\n\n=== 2. Audit Warm-Starting HPO (Budget=20 Trial, Rata-Rata 30 Ulangan) ===\n  Mild Drift   (opt=[0.28, 0.31]) | Cold=0.01220 | PureWarm=0.00071 | Hybrid(50/50)=0.00019\n  Severe Shift (opt=[0.80, 0.78]) | Cold=0.01653 | PureWarm=0.41578 | Hybrid(50/50)=0.03190\n\n=== 3. Audit Reproducibility Manifest Fingerprint ===\n  Canonical SHA-256 Run-1 : f976e0c71d14c97c8cd0d742...\n  Canonical SHA-256 Run-2 : f976e0c71d14c97c8cd0d742... | Identik 100%=True",
